// === Tab: mySketch ===
const sketch = (p) => {
    let H = 2048;
    let W = 2048;

    let min_width;

    let G;

    let SEED;

    let stars = [];


    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);

        SEED = p.random(998244353);

        p.randomSeed(SEED);
        p.noiseSeed(SEED);

        p.rectMode(p.CENTER);
        G.noStroke();
        let msc = p.pow(2, 8);
        let os1 = p.random();

        G.background(0,0,0,250);

        let sel = p.random();
        let bg_col;
        if(sel<.25) {bg_col=p.color(20,20,100,255);}
        else if (sel<0.5) {bg_col=p.color(70,20,70,255);}
        else if (sel<0.75) {bg_col=p.color(20,50,80,255);}
        else{bg_col=p.color(20,20,20,255);}
        for(let k=0;k < 9;++k){
            let sc = p.pow(2, k);
            for(let x=-0.5-1e-3;x<=0.5+1e-3;x+=1/sc){
                for(let y=-0.5-1e-3;y<=0.5+1e-3;y+=1/sc){
                    let v = p.noise((x+os1)*sc*.05, (y+os1+5)*sc*.05);
                    let a = .15;
                    bg_col.setAlpha(255*v*sc/msc*a);
                    G.fill(bg_col);
                    G.rect(W/2+x*W, H/2+y*H, W/sc, H/sc);
                }
            }
        }

        for(let i=0;i<2;++i){
            let red;;
            let green;;
            let blue;
            var sel = p.random();
            if(sel<.33){
                red = p.random(50, 100);
                green = red * p.random(0,.5);
                blue = p.random(0, 30);
            }
            else if(sel<.67){
                red = p.random(10, 30);
                green = red * p.random(0,.5);
                blue = p.random(80, 120);
            }
            else{
                red = p.random(30, 100);
                green = red * p.random(0,.5);
                blue = p.random(30, 100);
            }
            draw_nebula(
                p.color(red,green,blue),
                .03,
            );
        }

        sel = p.random();
        let base_color = [];
        if(sel < 0.2){
            base_color = [1, .7, .2];
        }
        else if(sel < 0.4){
            base_color = [.8, .4, .1];
        }
        else if(sel < 0.6){
            base_color = [.2, .6, .8];
        }
        else if(sel < 0.8){
            base_color = [.6, .2, .8];
        }
        else{
            base_color = [.6, .6, .6];
        }

        let n = 500;
        sel = p.random();
        if(sel < .25){
            let freq = p.random(5,10);
            var a = p.random(-p.PI/2,p.PI/2);
            for(let i=0;i<n*1.3;++i){
                let y = p.random();
                let x = p.lerp(.5+p.sin(y*freq+a)*.3, .5 + p.random(-.5*y, .5*y),y);
                x += p.randomGaussian(0, 0.2)*(y*1.4+.1);
                stars.push(new StarFlare(
                        x*W,
                        y*H,
                        p.max(W/10, p.randomGaussian(W/2*1.2, W/3))*(y*1.3+.2),
                        base_color
                    )
                );
            }
        }
        else if(sel<.5){
            let sg = (p.random()<.5)?p.PI*0.4:p.PI*1.4;
            let bi = p.random(-p.PI*.1, p.PI*.1);
            for(let i=0;i<n*1.2;++i){
                var x = p.random();
                var y = .5 + p.sin(x*p.PI*1.3 + bi + sg) * .3;
                y += p.randomGaussian(0, 0.2)*(y*1.4+.1);
                stars.push(new StarFlare(
                        x*W,
                        y*H,
                        p.max(W/10, p.randomGaussian(W/2*1.2, W/3))*(y*1.3+.2),
                        base_color
                    )
                );
            }
        }
        else if(sel < .75){
            let max_angle = p.TWO_PI*2.5;
            var bi = p.random(p.PI);
            for(let i=0;i<n*1.3;++i){
                let angle = p.sqrt(p.random())*max_angle;
                let f = angle/max_angle;
                let radius = (p.randomGaussian(0, 0.3) * W/2 * .3 + W/2*1.1) * f;
                var a = p.int(p.random(2)) * p.PI;
                stars.push(new StarFlare(
                        W/2+radius * p.cos(angle+a+bi),
                        H/2+radius * p.sin(angle+a+bi),
                        p.max(W/10, p.randomGaussian(W/2*1.2, W/3)),
                        base_color
                    )
                );
            }
        }
        else{
            var max_angle = p.TWO_PI*1.3;
            var sg = (p.random()<0.5?-1:1);
            let cx = (sg==-1)?W*.7:W*.3;
            let cy = H*0.328;
            for(let i=0;i<n*1.3;++i){
                var angle = p.sqrt(p.random())*max_angle;
                var f = angle/max_angle;
                var radius = p.randomGaussian(0, 0.6) * W/2 * .1 +
                (p.randomGaussian(0, 0.6) * W/2 * .4 + W/2*1.2) * f;
                stars.push(new StarFlare(
                        cx+radius * sg*p.cos(angle)*1.1,
                        cy+radius * p.sin(angle)*.9,
                        p.max(W/10, p.randomGaussian(W/2*1.2, W/3)*(f+.2)),
                        base_color
                    )
                );
            }
        }

        for(let i=0;i<200;++i){
            stars.push(new StarFlare(
                    p.random(0,W),
                    p.random(0,H),
                    p.max(W/40, p.randomGaussian(W/20, W/20)),
                    [1,1,1]
                )
            );
        }
    };

    p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);
        p.loop();
    }

    p.draw = () => {
        p.blendMode(p.BLEND);

        if(p.frameCount < 600){
            G.blendMode(p.ADD);
            G.noStroke();
            for(let i=0;i<stars.length;++i){
                stars[i].display();
            }
        }

        p.image(G, 0, 0, p.width, p.height, 0, 0, W, H);

    };

    function draw_nebula(col, scale){
        G.blendMode(p.ADD);
        var msc = p.pow(2, 9);
        let os = [p.random(5),p.random(5),p.random(5),p.random(5)];
        G.noStroke();
        for(let k=6;k < 9;++k){
            var sc = p.pow(2, k);
            let sc2 = p.pow(2, k);
            let oss=p.random(1);
            for(let x=-0.5-1e-3;x<=0.5+1e-3;x+=1/sc){
                for(let y=-0.5-1e-3;y<=0.5+1e-3;y+=1/sc){
                    var v = p.noise((x+os[0])*scale*sc, (y+os[1])*scale*sc);
                    var a = v*5;//p.pow(v, 4) * 15;
                    col.setAlpha(a*sc2/msc);
                    G.fill(col);
                    let osx = p.random(W/sc*oss) - W/sc*.5*oss;
                    let osy = p.random(H/sc*oss) - H/sc*.5*oss;
                    G.circle(W/2+x*W+osx, H/2+y*H+osy, W/sc*3);
                }
            }
        }
    }

    class StarFlare {
        pos;
        radius;
        rot;
        col;
        mxstep;
        freq;
        t;
        np;

        constructor(x,y,r, col){
            this.pos = p.createVector(x,y);
            this.radius = r;
            this.rot = p.random(p.TWO_PI);

            this.col = p.color(
                p.random(30,255)*col[0],
                p.random(30,255)*col[1],
                p.random(30,255)*col[2]
            );
            this.np = p.int(p.random(4,7));
            if(r>W*1.5){
                this.np = 10;
            }
            this.mxstep = 360+p.int(p.map(r/W,0,1,p.random(10),p.random(90,360),true));//p.int(p.random(380,500));
            this.freq = p.random(0.6,1.2);
            this.t = 1;
        }
        display() {
            if(p.frameCount<360){
                G.push();
                G.translate(this.pos.x, this.pos.y);
                G.rotate(this.rot);
                let r = this.radius/this.t;
                    this.col.setAlpha(this.t*.05);
                    G.fill(this.col);
                    for(let i=0;i<this.np;++i){
                        G.circle(r*p.cos(i*p.TWO_PI/this.np), r*p.sin(i*p.TWO_PI/this.np), r);
                    }

                G.pop();
            }
            else if (p.frameCount<this.mxstep){
                var os = p.frameCount - 360;
                var osx = p.cos(this.rot)*os;
                var osy = p.sin(this.rot)*os;
                var r = this.radius/2500*p.noise(this.pos.x*.05+this.t*.02)*17;
                this.col.setAlpha(p.noise(this.pos.y*.05+this.t*.02)*100);
                G.fill(this.col);
                G.circle(this.pos.x+osx+p.sin(os*.03*this.freq)*W/60, this.pos.y + osy, r);
            }

            this.t += 1;
        }
    }
};

new p5(sketch);

